// src/store/newsReducer.ts
import { ThunkAction } from 'redux-thunk';
import { Dispatch } from 'redux';
import { NewsState, NewsAction } from './types';
import { fetchNews } from '../services/newsService';
import { RootState } from './store';

// ✅ Define Thunk Type
export type AppThunk<ReturnType = void> = ThunkAction<ReturnType, RootState, unknown, NewsAction>;

// ✅ Define Action Types
export const FETCH_ARTICLES_REQUEST = 'FETCH_ARTICLES_REQUEST';
export const FETCH_ARTICLES_SUCCESS = 'FETCH_ARTICLES_SUCCESS';
export const FETCH_ARTICLES_FAILURE = 'FETCH_ARTICLES_FAILURE';
export const SET_FILTERS = 'SET_FILTERS';

// ✅ Initial State
const initialState: NewsState = {
  query: '',
  articles: [],
  status: 'idle',
  source: 'newsapi',
  date: '',
  category: '',
  author: '',
  sortBy: '',
  language: '',
};

// ✅ Reducer Function
const newsReducer = (state = initialState, action: NewsAction): NewsState => {
  switch (action.type) {
    case FETCH_ARTICLES_REQUEST:
      return { ...state, status: 'loading' };
    case FETCH_ARTICLES_SUCCESS:
      return { ...state, status: 'succeeded', articles: action.payload };
    case FETCH_ARTICLES_FAILURE:
      return { ...state, status: 'failed' };
    case SET_FILTERS:
      return { ...state, ...action.payload };
    default:
      return state;
  }
};

// ✅ Fix Thunk Action Dispatch
export const fetchArticles =
  ({ query, source, date, category, author, sortBy, language }: Partial<NewsState>): AppThunk =>
  async (dispatch: Dispatch<NewsAction>) => {
    dispatch({ type: FETCH_ARTICLES_REQUEST });

    try {
      const response = await fetchNews(query || 'latest', source || 'newsapi', date || '', category || '', author || '');

      let articles = response.data.articles || response.data.response?.docs || data.response?.results;

      // ✅ Manually filter articles if the API doesn't support author filtering
      if (author) {
        articles = articles.filter((article: any) =>
          (article.author?.toLowerCase() === author.toLowerCase()) || 
          (article.byline?.original?.toLowerCase() === author.toLowerCase()) ||
          (article.fields?.byline?.toLowerCase() === author.toLowerCase())
        );
      }

      dispatch({ type: FETCH_ARTICLES_SUCCESS, payload: response.articles || response.response?.docs || response.response?.results });
    } catch (error) {
      dispatch({ type: FETCH_ARTICLES_FAILURE });
    }
  };

export const setFilters = (filters: Partial<NewsState>): NewsAction => ({
  type: SET_FILTERS,
  payload: filters,
});

export default newsReducer;
